//! 📑️ Admitted Document styles, image octets and recursively bounded typed block trees.
use super::{SemioDocumentSnapshot,DocStyle,DocImage,DocBlock,DocRun,RunStyle,DocListItem,DocTableRow,DocTableCell,STDIO_SEMIODOCUMENT_DOCUMENT_SCHEMA};
use crate::standards::v1::subsets::base::schema::snapshot::native_decoding as native;
use semio_framework_value::native_decoding::NativeDecodeControl;
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits};
pub(super) fn decode(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<SemioDocumentSnapshot,String>{native::decode(payload,STDIO_SEMIODOCUMENT_DOCUMENT_SCHEMA,control,binary,document)}
fn f64(reader:&mut store::ByteReader<'_>)->Result<f64,String>{reader.read_f64_le().map_err(|e|e.to_string())}
fn boolean(value:u8)->Result<bool,String>{match value{0=>Ok(false),1=>Ok(true),_=>Err("invalid Document native boolean".into())}}
fn option<T>(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,read:impl FnOnce(&mut store::ByteReader<'_>,&mut NativeDecodeControl<'_>)->Result<T,String>)->Result<Option<T>,String>{match reader.read_u8().map_err(|e|e.to_string())?{0=>Ok(None),1=>read(reader,control).map(Some),_=>Err("invalid Document native optional presence".into())}}
fn run_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<DocRun,String>{Ok(DocRun{text:native::text(reader,control)?,style:RunStyle{bold:boolean(reader.read_u8().map_err(|e|e.to_string())?)?,italic:boolean(reader.read_u8().map_err(|e|e.to_string())?)?,underline:boolean(reader.read_u8().map_err(|e|e.to_string())?)?,size:option(reader,control,|reader,_|f64(reader))?,font:option(reader,control,native::text)?,color:option(reader,control,native::text)?,link:option(reader,control,native::text)?}})}
pub(crate) fn blocks_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<Vec<DocBlock>,String>{native::entities(entities,1,limits)?;native::binary_list(reader,control,limits,entities,|reader,control,entities|block_binary(reader,control,limits,entities))}
fn block_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<DocBlock,String>{control.scoped_depth(64,|control|{native::entities(entities,2,limits)?;Ok(match reader.read_u8().map_err(|e|e.to_string())?{
0=>{let style_id=option(reader,control,native::text)?;let runs=native::binary_list(reader,control,limits,entities,|reader,control,_|run_binary(reader,control))?;DocBlock::Paragraph{style_id,runs}},
1=>{let level=reader.read_u8().map_err(|e|e.to_string())?;let style_id=option(reader,control,native::text)?;let runs=native::binary_list(reader,control,limits,entities,|reader,control,_|run_binary(reader,control))?;DocBlock::Heading{level,style_id,runs}},
2=>{let ordered=boolean(reader.read_u8().map_err(|e|e.to_string())?)?;let items=native::binary_list(reader,control,limits,entities,|reader,control,entities|Ok(DocListItem{blocks:blocks_binary(reader,control,limits,entities)?}))?;DocBlock::List{ordered,items}},
3=>{let rows=native::binary_list(reader,control,limits,entities,|reader,control,entities|{let cells=native::binary_list(reader,control,limits,entities,|reader,control,entities|Ok(DocTableCell{blocks:blocks_binary(reader,control,limits,entities)?}))?;Ok(DocTableRow{cells})})?;DocBlock::Table{rows}},
4=>DocBlock::Code{language:option(reader,control,native::text)?,text:native::text(reader,control)?},5=>DocBlock::Quote{blocks:blocks_binary(reader,control,limits,entities)?},
6=>DocBlock::Image{image_id:native::text(reader,control)?,alt:native::text(reader,control)?,width:option(reader,control,|reader,_|f64(reader))?,height:option(reader,control,|reader,_|f64(reader))?},7=>DocBlock::PageBreak,_=>return Err("invalid Document native block kind".into())})})}
pub(crate) fn binary(body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioDocumentSnapshot,String>{let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|e|e.to_string())?!=1{return Err("unsupported Document native format".into())}let mut entities=0;native::entities(&mut entities,1,limits)?;let schema=native::text(&mut reader,control)?;let styles=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,_|Ok(DocStyle{id:native::text(reader,control)?,name:native::text(reader,control)?,based_on:option(reader,control,native::text)?}))?;let images=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,_|Ok(DocImage{id:native::text(reader,control)?,mime:native::text(reader,control)?,bytes:control.copy_bytes(native::bytes(reader)?)?}))?;let blocks=native::Owned::new(blocks_binary(&mut reader,control,limits,&mut entities)?);if reader.remaining()!=0{return Err("Document native trailing bytes".into())}Ok(SemioDocumentSnapshot{schema,styles,images,blocks:blocks.take()})}
fn bool_text(value:&str)->Result<bool,String>{match value{"0"=>Ok(false),"1"=>Ok(true),_=>Err("invalid Document native boolean".into())}}
fn optional_text<T>(value:&str,control:&mut NativeDecodeControl<'_>,read:impl FnOnce(&str,&mut NativeDecodeControl<'_>)->Result<T,String>)->Result<Option<T>,String>{if value=="[0]"{return Ok(None)}let[tag,value]=native::record(value,control)?;if tag!="1"{return Err("invalid Document native optional presence".into())}read(value,control).map(Some)}
fn number_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<f64,String>{control.scoped_stage(|control|{control.begin_stage(value.len())?;for _ in value.bytes(){control.step()?;}value.parse::<u64>().map(f64::from_bits).map_err(|_|"invalid Document native IEEE unsigned64 word".to_string())})}
fn run_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<DocRun,String>{let[text,style]=native::record(value,control)?;let[bold,italic,underline,size,font,color,link]=native::record(style,control)?;Ok(DocRun{text:native::hex_text(text,control)?,style:RunStyle{bold:bool_text(bold)?,italic:bool_text(italic)?,underline:bool_text(underline)?,size:optional_text(size,control,number_text)?,font:optional_text(font,control,native::hex_text)?,color:optional_text(color,control,native::hex_text)?,link:optional_text(link,control,native::hex_text)?}})}
pub(crate) fn blocks_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<Vec<DocBlock>,String>{native::entities(entities,1,limits)?;native::text_list(value,control,limits,entities,|value,control,entities|block_text(value,control,limits,entities))}
pub(crate) fn block_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<DocBlock,String>{control.scoped_depth(64,|control|{native::entities(entities,2,limits)?;let(tag,value)=value.split_at_checked(1).ok_or("Document native block tag missing")?;Ok(match tag{
"P"=>{let[style_id,runs]=native::record(value,control)?;let style_id=optional_text(style_id,control,native::hex_text)?;let runs=native::text_list(runs,control,limits,entities,|value,control,_|run_text(value,control))?;DocBlock::Paragraph{style_id,runs}},
"H"=>{let[level,style_id,runs]=native::record(value,control)?;let level=control.scoped_stage(|control|{control.begin_stage(level.len())?;for _ in level.bytes(){control.step()?;}level.parse::<u8>().map_err(|_|"invalid Document native unsigned8 heading".to_string())})?;let style_id=optional_text(style_id,control,native::hex_text)?;let runs=native::text_list(runs,control,limits,entities,|value,control,_|run_text(value,control))?;DocBlock::Heading{level,style_id,runs}},
"L"=>{let[ordered,items]=native::record(value,control)?;let ordered=bool_text(ordered)?;let items=native::text_list(items,control,limits,entities,|value,control,entities|{let[blocks]=native::record(value,control)?;Ok(DocListItem{blocks:blocks_text(blocks,control,limits,entities)?})})?;DocBlock::List{ordered,items}},
"T"=>{let[rows]=native::record(value,control)?;let rows=native::text_list(rows,control,limits,entities,|value,control,entities|{let[cells]=native::record(value,control)?;let cells=native::text_list(cells,control,limits,entities,|value,control,entities|{let[blocks]=native::record(value,control)?;Ok(DocTableCell{blocks:blocks_text(blocks,control,limits,entities)?})})?;Ok(DocTableRow{cells})})?;DocBlock::Table{rows}},
"C"=>{let[language,text]=native::record(value,control)?;DocBlock::Code{language:optional_text(language,control,native::hex_text)?,text:native::hex_text(text,control)?}},
"Q"=>{let[blocks]=native::record(value,control)?;DocBlock::Quote{blocks:blocks_text(blocks,control,limits,entities)?}},
"I"=>{let[image_id,alt,width,height]=native::record(value,control)?;DocBlock::Image{image_id:native::hex_text(image_id,control)?,alt:native::hex_text(alt,control)?,width:optional_text(width,control,number_text)?,height:optional_text(height,control,number_text)?}},"B"=>{let[]=native::record::<0>(value,control)?;DocBlock::PageBreak},_=>return Err("invalid Document native block kind".into())})})}
pub(crate) fn document(body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioDocumentSnapshot,String>{let fields=native::fields(body,["schema","styles","images","blocks"],control)?;let mut entities=0;native::entities(&mut entities,1,limits)?;let schema=native::hex_text(fields[0].ok_or("Document native schema missing")?,control)?;let styles=native::text_list(fields[1].unwrap_or("[]"),control,limits,&mut entities,|value,control,_|{let[id,name,based_on]=native::record(value,control)?;Ok(DocStyle{id:native::hex_text(id,control)?,name:native::hex_text(name,control)?,based_on:optional_text(based_on,control,native::hex_text)?})})?;let images=native::text_list(fields[2].unwrap_or("[]"),control,limits,&mut entities,|value,control,_|{let[id,mime,bytes]=native::record(value,control)?;Ok(DocImage{id:native::hex_text(id,control)?,mime:native::hex_text(mime,control)?,bytes:native::hex(bytes,control)?})})?;let blocks=blocks_text(fields[3].unwrap_or("[]"),control,limits,&mut entities)?;Ok(SemioDocumentSnapshot{schema,styles,images,blocks})}
